package xyz.znix.xftl;

import xyz.znix.xftl.game.MainGame;
import xyz.znix.xftl.sys.PackagedLog;

public class App {
    public static void main(String[] args) {
        // The packaged game has no console, so it keeps a log
        PackagedLog.start();

        MainGame.CommandLineArgs cla = new MainGame.CommandLineArgs();

        // Parse the command-line args
        for (int i = 0; i < args.length; i++) {
            String arg = args[i];
            if (arg.equals("--new-game")) {
                cla.newGameShip = args[++i];
            } else if (arg.equals("--load-debug-save")) {
                cla.debugLoad = args[++i];
            } else {
                System.err.printf("Unknown command-line argument '%s'%n", arg);
                System.exit(1);
            }
        }

        try {
            Utils.INSTANCE.startSlick(new MainGame(cla));
        } catch (Throwable ex) {
            // Make sure a crash ends up in the log
            System.err.println("The game crashed:");
            ex.printStackTrace();
            throw ex;
        }
    }
}
